  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "In baboons, I-ketanserin showed rapid initial brain uptake that remained constant from 20 minutes to 2 hours after injection, demonstrating meaningful BBB penetration after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "[18F]altanserin showed sufficient brain uptake in a quantitative micro-PET study in rats, with a distribution consistent with known 5-HT2A receptor localization, supporting CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "In healthy human volunteers, ITI-007 rapidly penetrated the brain after systemic administration, with extended and dose-related striatal D2 receptor occupancy, directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple structurally related CNS-active ligands show robust brain uptake after systemic administration across baboons, rats, and humans, strongly supporting meaningful CNS access for the query molecule.",
  "evidence_gaps": [
    "No direct query-specific brain or plasma PK data are available; prediction relies on close analog evidence.",
    "No negative or contradictory BBB/efflux records were provided to weigh against the positive in vivo uptake evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

